    const grid = [];
    for (let i = 0; i < n; i++) {
        const row = new Int32Array(m);
        for (let j = 0; j < m; j++) {
            row[j] = nextInt();
        }
        grid.push(row);
    }

    // Configuração 0: (i + j) par -> ímpar (1), (i + j) ímpar -> par (0)
    // Configuração 1: (i + j) par -> par (0), (i + j) ímpar -> ímpar (1)
    let cost0 = 0;
    let cost1 = 0;

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < m; j++) {
            const currentParity = grid[i][j] & 1;
            const targetParity0 = ((i + j) & 1) === 0 ? 1 : 0;
            if (currentParity !== targetParity0) {
                cost0++;
            } else {
                cost1++;
            }
        }
    }

    const bestTargetEven = (cost0 <= cost1) ? 1 : 0;
    const minCost = Math.min(cost0, cost1);

    const out = [];
    out.push(minCost.toString());

    for (let i = 0; i < n; i++) {
        const rowVals = [];
        for (let j = 0; j < m; j++) {
            let val = grid[i][j];
            const targetParity = ((i + j) & 1) === 0 ? bestTargetEven : (1 - bestTargetEven);
            if ((val & 1) !== targetParity) {
                val++;
            }
            rowVals.push(val);
        }
        out.push(rowVals.join(' '));
    }

    console.log(out.join('\n'));
}

solve();
